nner join ordermas on ordermas.ordid=trs_del2.ordid  LEFT OUTER JOIN Mas_Bank Mas_Bank on Mas_Bank.BankId =Mas_Exporter.BankId   left join Mas_SalesGrp on Trs_SalInv.Coycode = Mas_SalesGrp.Coycode  left JOIN SuppOrdMas ON Trs_Del2.SuppOrdid = SuppOrdMas.SuppOrdId  LEFT JOIN Mas_UOM ON Mas_Fabric.PriUomID = Mas_Uom.UomID
