 WHERE Trs_SalInv.Id=''' + @id + '''  GROUP BY Mas_Exporter.ExporterName, Case When Trs_Salinv.inv_Prefix is Null or Trs_Salinv.inv_Prefix  = '''' then RTRIM(Trs_Salinv.Invno) + ''/'' + RTRIM(Trs_Salinv.Finyear) ELSE RTRIM(Trs_Salinv.inv_Prefix) +''/''+ RTRIM(Trs_Salinv.Invno) + ''/'' + RTRIM(Trs_Salinv.Finyear) END , Trs_Salinv.Finyear, Trs_Salinv.Invdt,Trs_Del1.DocNo,StockTable.YF,Mas_Count.CountName,Mas_Color.ColorDesc,Mas_Fabric.Fabdesc,Trs_Del1.Finyear,Trs_Del1.Dt,Trs_Salinv.ID,Mas_Exporter.CST , Mas_Exporter.TIN ,Mas_Exporter.Phone,Mas_Party.Pname, Mas_Party.Phone ,Mas_Party.CST, Mas_Party.TIN, Mas_Design.DesignDesc, Mas_Buyer.BuyerName, Mas_Buyer.Phone  , Trs_Salinv.PartyType, Mas_Acc.Acc_Descr, cast(Mas_Exporter.ExporterAddress as Varchar), cast(Mas_Party.Paddress as varchar(2000)), Cast(Mas_Buyer.BuyerAddress as Varchar(2000)),isnull(Mas_PartyState.StateName,'''') ,isnull(Mas_PartyState.StateCode,0),isnull(Mas_State.StateName,''''),Isnull(Mas_State.StateCode,0),Mas_HSN.HSNCode,Mas_Exporter.Stateid,Pro_ReqKnitt2.SGSTPer,Mas_Party.Stateid, Pro_ReqKnitt2.CGSTPer,Pro_ReqKnitt2.IGSTPer,Trs_Del1.EwayBillNo,Trs_Del1.EwayBillDt,Pro_ReqKnitt2.Cost,Mas_Exporter.GSTNo,Mas_Party.GSTNo,Mas_Vehicle.VName,Trs_Salinv.ReverseCharge,Trs_Salinv.TransPortationMode,Trs_Del2.Rate,Mas_Count.BrandedFlag,Mas_HSN.UnitRate,Mas_HSN.NBPercH,MaS_HSN.NBPercL,Mas_HSN.BPercH,Mas_HSN.BPercL,Mas_Fabric.BrandedFlag,Mas_HSN2.UnitRate,Mas_HSN2.NBPercH,MaS_HSN2.NBPercL,Mas_HSN2.BPercH,Mas_HSN2.BPercL,Mas_HSN2.HSNCode,MAs_HSN3.UnitRate,MAs_HSN3.NBPercH,MAs_HSN3.NBPercL,MAs_HSN3.BPercH,MAs_HSN3.BPercL,MAs_HSN3.HSNCode,Mas_Party.Paddress,Mas_Exporter.ExporterAddress,Mas_Acc.BrandedFlag,ordermas.Jobno,OrderMas.Finyear, OrderMas.BuyOrdNo, ordermas.OrdId,IsNull(Mas_Bank.CurrAcc,'''')  ,IsNull(Mas_Bank.IFSCCode,''''),IsNull(CostName,'''') ,Trs_Salinv.InvType,Sales_Inv_Yarn_Prefix,Sales_Inv_Fabric_Prefix,Sales_Inv_Acc_Prefix,Trs_Salinv.Invno,Mas_HSN4.UnitRate,Mas_HSN4.NBPercH,MaS_HSN4.NBPercL,Mas_HSN4.B